--- import '../styles/global.css';
export interface Props { title?: string; description?: string; }
const { title = 'Fitri Zahwa — Portfolio', description = 'UI/UX Designer, Illustrator & Pixel Artist based in Indonesia', } = Astro.props; ---
<!doctype html> <html lang="en" class="h-full"> <head> <meta charset="UTF-8" /> <meta name="viewport" content="width=device-width, initial-scale=1.0" /> <title>{title}</title> <meta name="description" content={description} /> <link rel="preconnect" href="https://fonts.googleapis.com" /> <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin /> <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=DM+Sans:wght@400;500;600;700&family=Space+Mono:wght@400;700&display=swap" rel="stylesheet" /> </head> <body class="h-full bg-[#F5F5F5] text-gray-900 font-sans antialiased"> <slot /> </body> </html>

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  *, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
    cursor: none !important;
  }

  html, body {
    height: 100%;
    font-family: 'Inter', system-ui, sans-serif;
    -webkit-font-smoothing: antialiased;
  }
}

@layer components {
  /* Pink cursor dot indicator */
  .cursor-dot {
    width: 8px;
    height: 8px;
    background: #FF49DB;
    border-radius: 50%;
    pointer-events: none;
    position: fixed;
    transform: translate(-50%, -50%);
    z-index: 9999;
    transition: opacity 0.2s;
    mix-blend-mode: multiply;
  }

  /* Nav item hover arrow slide-in */
  .nav-item .arrow-icon {
    opacity: 0;
    transform: translateX(-4px);
    transition: opacity 0.2s ease, transform 0.2s ease;
  }
  .nav-item:hover .arrow-icon {
    opacity: 1;
    transform: translateX(0);
  }
}

@layer utilities {
  .scrollbar-hide {
    -ms-overflow-style: none;
    scrollbar-width: none;
  }
  .scrollbar-hide::-webkit-scrollbar {
    display: none;
  }
}

/* Pulse animation for center node ring */
@keyframes pulse-ring {
  0%   { r: 44; opacity: 0.5; }
  70%  { r: 64; opacity: 0;   }
  100% { r: 44; opacity: 0;   }
}

.pulse-ring {
  animation: pulse-ring 2.8s ease-out infinite;
}

/* Floating label pink fade */
@keyframes float-in {
  from { opacity: 0; transform: translateY(6px); }
  to   { opacity: 1; transform: translateY(0); }
}

.float-label {
  animation: float-in 0.4s ease forwards;
}

